-- Consultas guardadas en el Gestor SQL de PrestaShop (Parámetros avanzados > Base de datos > Gestor SQL).
-- Copia de seguridad: si se borran, recrearlas con el mismo nombre. El script scripts/pos_refresh.js
-- las ejecuta por id (POS_QUERY_IDS). Orden de ejecución: una a la vez (el gestor se cuelga con varias).
-- Definiciones: TPV = ps_orders.module LIKE 'InnovaCommerceTPV%' (sufijo = tienda; sin sufijo = 'Barakaldo').
-- Clientes genéricos de caja: id_customer 1 y 2703803 (se excluyen del análisis por cliente).
-- Marca BVS = ps_manufacturer 35 ('BVS Vet Shop'); Bawi = 271. Latas BVS = fabricante 35 y categorías 534-539.
-- ps_prestapos_discount_log (promos del TPV) solo existe desde el 11-jun-2026.
-- Regla del Gestor: no unir subconsultas derivadas con ps_order_detail (se usa od.id_order >= N).

-- ── 758 · BVS_pos_store_monthly → pos_store_monthly (v2: añade coupon_excl, cupones sin IVA) ──────────────────────────────────────────
SELECT YEAR(o.date_add) y, MONTH(o.date_add) m, IF(TRIM(REPLACE(o.module,'InnovaCommerceTPV',''))='','Barakaldo',TRIM(REPLACE(o.module,'InnovaCommerceTPV',''))) store, COUNT(*) tickets, SUM(o.id_customer NOT IN (1,2703803)) tickets_ident, COUNT(DISTINCT CASE WHEN o.id_customer NOT IN (1,2703803) THEN o.id_customer END) customers, ROUND(SUM(o.total_paid_tax_incl),2) revenue, ROUND(SUM(o.total_paid_tax_excl),2) revenue_excl, ROUND(SUM(o.total_discounts_tax_incl),2) coupon_discount, ROUND(SUM(IFNULL(dl.dto,0)),2) promo_discount, SUM(dl.id_order IS NOT NULL OR cr.id_order IS NOT NULL) tickets_discount, ROUND(SUM(o.total_discounts_tax_excl),2) coupon_excl FROM ps_orders o LEFT JOIN (SELECT id_order, SUM(total_promotion_discount) dto FROM ps_prestapos_discount_log GROUP BY id_order) dl ON dl.id_order=o.id_order LEFT JOIN (SELECT DISTINCT r.id_order FROM ps_order_cart_rule r WHERE r.id_order>=887630) cr ON cr.id_order=o.id_order WHERE o.valid=1 AND o.module LIKE 'InnovaCommerceTPV%' AND o.date_add>='2024-01-01' GROUP BY y, m, store ORDER BY y, m, store;

-- ── 761 · BVS_pos_bvs_monthly → pos_bvs_monthly ──────────────────────────────────────────────
SELECT YEAR(o.date_add) y, MONTH(o.date_add) m, IF(TRIM(REPLACE(o.module,'InnovaCommerceTPV',''))='','Barakaldo',TRIM(REPLACE(o.module,'InnovaCommerceTPV',''))) store, IF(p.id_manufacturer=35,'BVS Vet Shop','Bawi') brand, COUNT(DISTINCT od.id_order) tickets, SUM(od.product_quantity) units, ROUND(SUM(od.total_price_tax_incl),2) revenue FROM ps_order_detail od JOIN ps_orders o ON o.id_order=od.id_order AND o.valid=1 AND o.module LIKE 'InnovaCommerceTPV%' AND o.date_add>='2024-01-01' JOIN ps_product p ON p.id_product=od.product_id AND p.id_manufacturer IN (35,271) WHERE od.id_order>=887630 GROUP BY y, m, store, brand ORDER BY y, m, store, brand;

-- ── 763 · BVS_pos_codes_monthly → pos_codes_monthly ──────────────────────────────────────────
SELECT YEAR(o.date_add) y, MONTH(o.date_add) m, 'cupon' src, CASE WHEN r.name LIKE '%apertura%' THEN '20% apertura' WHEN r.name LIKE 'Descuento%' THEN 'Descuento manual en caja' ELSE r.name END code, COUNT(DISTINCT r.id_order) tickets, COUNT(DISTINCT CASE WHEN o.id_customer NOT IN (1,2703803) THEN o.id_customer END) customers, ROUND(SUM(r.value),2) discount, ROUND(SUM(o.total_paid_tax_incl),2) revenue FROM ps_order_cart_rule r JOIN ps_orders o ON o.id_order=r.id_order AND o.valid=1 AND o.module LIKE 'InnovaCommerceTPV%' AND o.date_add>='2024-01-01' WHERE r.id_order>=887630 GROUP BY y, m, code UNION ALL SELECT YEAR(o.date_add) y, MONTH(o.date_add) m, 'promo_pos' src, CASE WHEN jt.name LIKE '%apertura%' THEN '20% apertura' WHEN jt.name LIKE 'Descuento%' THEN 'Descuento manual en caja' ELSE jt.name END code, COUNT(DISTINCT l.id_order) tickets, COUNT(DISTINCT CASE WHEN o.id_customer NOT IN (1,2703803) THEN o.id_customer END) customers, ROUND(SUM(jt.amount),2) discount, ROUND(SUM(o.total_paid_tax_incl),2) revenue FROM ps_prestapos_discount_log l JOIN ps_orders o ON o.id_order=l.id_order AND o.valid=1 JOIN JSON_TABLE(l.discount_lines,'$[*]' COLUMNS(name VARCHAR(120) PATH '$.name', amount DECIMAL(10,2) PATH '$.amount')) jt GROUP BY y, m, code ORDER BY y, m, tickets DESC;

-- ── 766 · BVS_pos_tickets (exportar CSV; ~133K filas) → entrada de la retención ──────────────────
SELECT o.id_order, o.id_customer, DATE(o.date_add) d, ROUND(o.total_paid_tax_incl,2) t, IF(TRIM(REPLACE(o.module,'InnovaCommerceTPV',''))='','Barakaldo',TRIM(REPLACE(o.module,'InnovaCommerceTPV',''))) store FROM ps_orders o WHERE o.valid=1 AND o.date_add>='2024-10-01' AND o.module LIKE 'InnovaCommerceTPV%' AND o.id_customer NOT IN (1,2703803);

-- ── 767 · BVS_pos_ticket_codes (exportar CSV; ~15K filas) ───────────────────────────────────────
-- r.id_order>=1500000 debe quedar POR DEBAJO del primer pedido de la ventana (11-jun-2026).
SELECT r.id_order, 'cupon' src, CASE WHEN r.name LIKE '%apertura%' THEN '20% apertura' WHEN r.name LIKE 'Descuento%' THEN 'Descuento manual en caja' ELSE r.name END code FROM ps_order_cart_rule r JOIN ps_orders o ON o.id_order=r.id_order AND o.valid=1 AND o.module LIKE 'InnovaCommerceTPV%' AND o.date_add>='2025-01-01' WHERE r.id_order>=1500000 UNION ALL SELECT l.id_order, 'promo_pos' src, CASE WHEN jt.name LIKE '%apertura%' THEN '20% apertura' WHEN jt.name LIKE 'Descuento%' THEN 'Descuento manual en caja' ELSE jt.name END code FROM ps_prestapos_discount_log l JOIN JSON_TABLE(l.discount_lines,'$[*]' COLUMNS(name VARCHAR(120) PATH '$.name')) jt;

-- ── 768 · BVS_pos_latas (exportar CSV; ~16K filas) ──────────────────────────────────────────────
SELECT od.id_order, SUM(od.product_quantity) units FROM ps_order_detail od JOIN ps_orders o ON o.id_order=od.id_order AND o.valid=1 AND o.module LIKE 'InnovaCommerceTPV%' AND o.date_add>='2024-10-01' JOIN ps_product p ON p.id_product=od.product_id AND p.id_manufacturer=35 AND p.id_category_default IN (534,535,536,537,538,539) WHERE od.id_order>=1100000 GROUP BY od.id_order;

-- ═══ v2 (30-oct-2026): margen, cesta, hora y día, zona, web+tienda ═══════════════════════════════════
-- Las líneas de ps_order_detail ya van NETAS de cupón y promo (venta de líneas ≈ total pagado sin IVA ±0,2%):
-- no se resta ningún descuento más al calcular el margen. Coste = original_wholesale_price (coste de catálogo al pedir).

-- ── 772 · BVS_pos_margin_monthly → pos_margin_monthly ───────────────────────────────────────────
SELECT YEAR(o.date_add) y, MONTH(o.date_add) m, IF(TRIM(REPLACE(o.module,'InnovaCommerceTPV',''))='','Barakaldo',TRIM(REPLACE(o.module,'InnovaCommerceTPV',''))) store, COUNT(DISTINCT od.id_order) tickets, ROUND(SUM(od.total_price_tax_excl),2) rev_lines, ROUND(SUM(IF(od.original_wholesale_price>0, od.total_price_tax_excl,0)),2) rev_known, ROUND(SUM(od.original_wholesale_price*od.product_quantity),2) cost FROM ps_order_detail od JOIN ps_orders o ON o.id_order=od.id_order AND o.valid=1 AND o.module LIKE 'InnovaCommerceTPV%' AND o.date_add>='2024-01-01' WHERE od.id_order>=887630 GROUP BY y, m, store ORDER BY y, m, store;

-- ── 773 · BVS_pos_ticket_brands (exportar CSV) → cesta por marca y margen por código ────────────
-- od.id_order>=2100000 debe quedar POR DEBAJO del primer pedido de la ventana (11-jun-2026 = 2.109.583).
SELECT od.id_order, IFNULL(m.name,'Sin marca') brand, SUM(od.product_quantity) units, ROUND(SUM(od.total_price_tax_excl),2) rev, ROUND(SUM(IF(od.original_wholesale_price>0, od.total_price_tax_excl,0)),2) rev_known, ROUND(SUM(od.original_wholesale_price*od.product_quantity),2) cost FROM ps_order_detail od JOIN ps_orders o ON o.id_order=od.id_order AND o.valid=1 AND o.module LIKE 'InnovaCommerceTPV%' AND o.date_add>='2026-06-11' LEFT JOIN ps_product p ON p.id_product=od.product_id LEFT JOIN ps_manufacturer m ON m.id_manufacturer=p.id_manufacturer WHERE od.id_order>=2100000 GROUP BY od.id_order, brand;

-- ── 774 · BVS_pos_hourly (CSV) → pos_hourly (dow 1=lunes) ───────────────────────────────────────
SELECT YEAR(o.date_add) y, MONTH(o.date_add) m, IF(TRIM(REPLACE(o.module,'InnovaCommerceTPV',''))='','Barakaldo',TRIM(REPLACE(o.module,'InnovaCommerceTPV',''))) store, WEEKDAY(o.date_add)+1 dow, HOUR(o.date_add) h, COUNT(*) tickets, ROUND(SUM(o.total_paid_tax_incl),2) revenue FROM ps_orders o WHERE o.valid=1 AND o.module LIKE 'InnovaCommerceTPV%' AND o.date_add>='2024-10-01' GROUP BY y, m, store, dow, h ORDER BY y, m, store, dow, h;

-- ── 775 · BVS_pos_zone (CSV) → pos_zone (código postal de la dirección del cliente identificado) ─
SELECT YEAR(o.date_add) y, MONTH(o.date_add) m, IF(TRIM(REPLACE(o.module,'InnovaCommerceTPV',''))='','Barakaldo',TRIM(REPLACE(o.module,'InnovaCommerceTPV',''))) store, a.postcode cp, MIN(a.city) city, COUNT(*) tickets, ROUND(SUM(o.total_paid_tax_incl),2) revenue FROM ps_orders o JOIN ps_address a ON a.id_address=o.id_address_delivery WHERE o.valid=1 AND o.module LIKE 'InnovaCommerceTPV%' AND o.date_add>='2025-01-01' AND o.id_customer NOT IN (1,2703803) AND a.postcode<>'' GROUP BY y, m, store, cp ORDER BY y, m, store, tickets DESC;

-- ── 776 · BVS_pos_web_quarter → clientes web por trimestre (entra en pos_channel_quarter) ───────
SELECT YEAR(date_add) y, QUARTER(date_add) q, COUNT(DISTINCT id_customer) web_customers, COUNT(*) orders, ROUND(SUM(total_paid_tax_incl)) rev FROM ps_orders WHERE valid=1 AND module NOT LIKE 'InnovaCommerceTPV%' AND payment NOT LIKE '%Amazon%' AND payment NOT LIKE '%Marketplace%' AND module NOT LIKE 'channable%' AND date_add>='2024-10-01' GROUP BY y, q ORDER BY y, q;

-- ── 777 · BVS_pos_cust_web (CSV) → pedidos web de los clientes de tienda, por cliente y trimestre ─
SELECT w.id_customer, YEAR(w.date_add) y, QUARTER(w.date_add) q, COUNT(*) n, ROUND(SUM(w.total_paid_tax_incl)) rev FROM ps_orders w JOIN (SELECT DISTINCT id_customer FROM ps_orders WHERE module LIKE 'InnovaCommerceTPV%' AND valid=1 AND date_add>='2024-10-01' AND id_customer NOT IN (1,2703803)) t ON t.id_customer=w.id_customer WHERE w.valid=1 AND w.module NOT LIKE 'InnovaCommerceTPV%' AND w.payment NOT LIKE '%Amazon%' AND w.payment NOT LIKE '%Marketplace%' AND w.module NOT LIKE 'channable%' AND w.date_add>='2024-10-01' GROUP BY w.id_customer, y, q;
